"""Spreadsheets, Word documents and the finder. Fixtures are generated by independent libraries (openpyxl, python-docx)."""
from __future__ import annotations

import datetime as dt
import shutil
import zipfile
from pathlib import Path
from typing import Any

import openpyxl
import pytest
from docx import Document

from hearth import docxio, finder, readers, sheets
from hearth.tools import Ctx, run_tool
from hearth.tools_base import Budget
from tests.conftest import Asker


def run(ctx: Ctx, name: str, **args: Any) -> str:
    return run_tool(ctx, name, args)


def make_people(path: Path) -> None:
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "People"
    ws.append(["Name", "Age", "Country", "Joined", "Score"])
    ws.append(["Jack", 15, "India", dt.date(2024, 3, 9), 1.5])
    ws.append(["Jill", 22, "France", dt.date(2023, 1, 2), 2])
    ws.append(["Jackie", 41, "Spain", dt.date(2022, 5, 5), "=B4*2"])
    ws2 = wb.create_sheet("Other")
    ws2.append(["Item", "Qty"])
    ws2.append(["Jack's hat", 3])
    wb.save(path)


@pytest.fixture
def people(root: Path) -> Path:
    p = root / "people.xlsx"
    make_people(p)
    return p


def values(path: Path, sheet: str = "People") -> list[list[Any]]:
    wb = openpyxl.load_workbook(path)
    return [[c.value for c in row] for row in wb[sheet].iter_rows()]


# ------------------------------------------------------------------ sheets: reading

def test_load_xlsx_reads_values_dates_and_formulas(people: Path):
    books = sheets.load(str(people))
    sh = books[0]
    assert [b.name for b in books] == ["People", "Other"]
    assert sh.headers() == {1: "Name", 2: "Age", 3: "Country", 4: "Joined", 5: "Score"}
    assert sh.get(2, 1) == "Jack" and sh.get(2, 2) == "15" and sh.get(2, 5) == "1.5"
    assert sh.get(2, 4) == "2024-03-09"
    assert (4, 5) in sh.formulas


def test_headers_only_is_cheap_but_correct(people: Path):
    sh = sheets.load(str(people), headers_only=True)[0]
    assert sh.headers()[3] == "Country"


def test_resolve_column_by_header_letter_and_part(people: Path):
    sh = sheets.load(str(people))[0]
    assert sheets.resolve_column(sh, "age") == 2
    assert sheets.resolve_column(sh, "C") == 3
    assert sheets.resolve_column(sh, "count") == 3
    with pytest.raises(sheets.SheetError, match="no column"):
        sheets.resolve_column(sh, "salary")
    with pytest.raises(sheets.SheetError):
        sheets.resolve_column(sh, "")


def test_to_text_lists_every_sheet(people: Path):
    text = sheets.to_text(str(people))
    assert "Jack" in text and "Other" in text and "Jack's hat" in text


def test_bad_workbook_is_a_clean_error(root: Path):
    bad = root / "bad.xlsx"
    bad.write_bytes(b"not a zip")
    with pytest.raises(sheets.SheetError):
        sheets.load(str(bad))


# ------------------------------------------------------------------ sheets: editing

def test_set_cell_changes_only_that_cell(people: Path):
    before = values(people)
    sh = sheets.load(str(people))[0]
    sheets.set_cell(str(people), sh, 2, 2, "98")
    after = values(people)
    assert after[1][1] == 98
    after[1][1] = before[1][1]
    assert after == before


def test_set_cell_keeps_date_style_and_other_sheets(people: Path):
    sh = sheets.load(str(people))[0]
    sheets.set_cell(str(people), sh, 3, 4, "2025-12-31")
    wb = openpyxl.load_workbook(people)
    cell = wb["People"]["D3"]
    assert cell.value == dt.datetime(2025, 12, 31) and "yy" in cell.number_format.lower()
    assert values(people, "Other")[1] == ["Jack's hat", 3]


def test_set_cell_text_and_empty_cell_and_new_row(people: Path):
    sh = sheets.load(str(people))[0]
    sheets.set_cell(str(people), sh, 2, 1, 'Jack "J" & <Co>')
    sheets.set_cell(str(people), sh, 3, 6, "note")      # a column past the last used one
    sheets.set_cell(str(people), sh, 7, 1, "Newbie")    # a row past the last used one
    v = values(people)
    assert v[1][0] == 'Jack "J" & <Co>' and v[2][5] == "note" and v[6][0] == "Newbie"


def test_set_cell_refuses_formulas_and_macros_and_out_of_range(people: Path, root: Path):
    sh = sheets.load(str(people))[0]
    with pytest.raises(sheets.SheetError, match="formula"):
        sheets.set_cell(str(people), sh, 4, 5, "1")
    with pytest.raises(sheets.SheetError, match="outside"):
        sheets.set_cell(str(people), sh, 0, 1, "1")
    macro = root / "m.xlsm"
    shutil.copy(people, macro)
    with pytest.raises(sheets.SheetError, match="macro"):
        sheets.set_cell(str(macro), sheets.load(str(macro))[0], 2, 2, "1")


def test_set_cell_asks_excel_to_recalculate_when_formulas_exist(people: Path):
    sh = sheets.load(str(people))[0]
    sheets.set_cell(str(people), sh, 4, 2, "50")
    with zipfile.ZipFile(people) as z:
        wb_xml = z.read("xl/workbook.xml").decode()
    assert 'fullCalcOnLoad="1"' in wb_xml
    assert values(people)[3][4] == "=B4*2"


def test_failed_write_leaves_the_file_intact(people: Path, monkeypatch: pytest.MonkeyPatch):
    data = people.read_bytes()
    sh = sheets.load(str(people))[0]
    monkeypatch.setattr(sheets, "_patch_sheet_xml", lambda *a, **k: (_ for _ in ()).throw(sheets.SheetError("boom")))
    with pytest.raises(sheets.SheetError):
        sheets.set_cell(str(people), sh, 2, 2, "1")
    assert people.read_bytes() == data and not list(people.parent.glob("*.hearth-tmp"))


# ------------------------------------------------------------------ csv / tsv

def test_csv_roundtrip_keeps_delimiter_eol_and_bom(root: Path):
    p = root / "d.csv"
    p.write_bytes("﻿Name;Age\r\nJack;15\r\nJill;22\r\n".encode())
    sh = sheets.load(str(p))[0]
    assert sh.headers() == {1: "Name", 2: "Age"} and sh.get(2, 2) == "15"
    sheets.set_cell(str(p), sh, 2, 2, "98")
    assert p.read_bytes() == "﻿Name;Age\r\nJack;98\r\nJill;22\r\n".encode()


def test_csv_quotes_values_that_need_it_and_tsv_works(root: Path):
    p = root / "d.csv"
    p.write_text("Name,Age\nJack,15\n", encoding="utf-8")
    sheets.set_cell(str(p), sheets.load(str(p))[0], 2, 1, 'Smith, "J"')
    assert sheets.load(str(p))[0].get(2, 1) == 'Smith, "J"'
    t = root / "d.tsv"
    t.write_text("Name\tAge\nJack\t15\n", encoding="utf-8")
    sheets.set_cell(str(t), sheets.load(str(t))[0], 2, 2, "7")
    assert t.read_text() == "Name\tAge\nJack\t7\n"


# ------------------------------------------------------------------ docx

def make_docx(path: Path) -> None:
    d = Document()
    d.add_paragraph("Meeting notes")
    p = d.add_paragraph()
    p.add_run("The deposit is ")
    p.add_run("1200").bold = True
    p.add_run(" dollars & due Friday.")
    d.add_paragraph("Second 1200 here")
    d.save(path)


@pytest.fixture
def word(root: Path) -> Path:
    p = root / "notes.docx"
    make_docx(p)
    return p


def test_docx_replace_across_runs_keeps_formatting(word: Path):
    xml = docxio.load(str(word))
    assert docxio.count(xml, "deposit is 1200 dollars") == 1
    new, n = docxio.replace(xml, "deposit is 1200 dollars", "deposit is 900 dollars", False)
    assert n == 1
    docxio.save(str(word), new)
    doc = Document(word)
    assert doc.paragraphs[1].text == "The deposit is 900 dollars & due Friday."
    assert doc.paragraphs[2].text == "Second 1200 here"


def test_docx_replace_all_and_special_characters(word: Path):
    xml = docxio.load(str(word))
    new, n = docxio.replace(xml, "1200", "<5> & more", True)
    assert n == 2
    docxio.save(str(word), new)
    texts = [p.text for p in Document(word).paragraphs]
    assert "<5> & more" in texts[1] and texts[2] == "Second <5> & more here"


def test_docx_append_goes_before_section_properties(word: Path):
    docxio.save(str(word), docxio.append(docxio.load(str(word)), "Line one\nLine two"))
    texts = [p.text for p in Document(word).paragraphs]
    assert texts[-2:] == ["Line one", "Line two"]


def test_docx_diff_shows_only_changed_paragraphs(word: Path):
    xml = docxio.load(str(word))
    new, _ = docxio.replace(xml, "Meeting", "Team", False)
    d = docxio.diff(xml, new)
    assert "- Meeting notes" in d and "+ Team notes" in d and "deposit" not in d
    assert docxio.diff(xml, xml) == "(no visible change)"


def test_docx_errors(root: Path, word: Path):
    with pytest.raises(docxio.DocxError):
        docxio.replace(docxio.load(str(word)), "", "x", False)
    bad = root / "bad.docx"
    bad.write_bytes(b"PK")
    with pytest.raises(docxio.DocxError):
        docxio.load(str(bad))


# ------------------------------------------------------------------ the finder

def test_finder_matches_column_headers(ctx: Ctx, people: Path, root: Path):
    other = root / "docs" / "inventory.xlsx"
    wb = openpyxl.Workbook()
    wb.active.append(["Item", "Price"])
    wb.save(other)
    found, _ = finder.search(ctx, "Country", "excel")
    assert [f.path for f in found] == [str(people)]
    assert "Country" in found[0].why


def test_finder_by_content_kind_and_filename(ctx: Ctx, word: Path, people: Path):
    ctx.index.sync()
    assert [f.path for f in finder.search(ctx, "deposit", "word")[0]] == [str(word)]
    assert finder.kind_of(str(word)) == "word" and finder.kind_of("a.pdf") == "pdf" and finder.kind_of("a.bin") == "other"
    names = [f.path for f in finder.search(ctx, "people")[0]]
    assert str(people) in names


def test_finder_skips_broken_workbooks(ctx: Ctx, root: Path, people: Path):
    (root / "broken.xlsx").write_bytes(b"junk")
    (root / "~$lock.xlsx").write_bytes(b"junk")
    assert [f.path for f in finder.scan_headers(ctx, "country", [str(root)], Budget())] == [str(people)]
    assert finder.scan_headers(ctx, " ", [str(root)], Budget()) == []


# ------------------------------------------------------------------ tools

def test_search_text_tool_remembers_results(ctx: Ctx, people: Path):
    out = run(ctx, "search_text", query="Country", kind="excel")
    assert str(people) in out and ctx.found == [str(people)] and "Name every file" in out
    assert "kind must be" in run(ctx, "search_text", query="x", kind="banana")
    assert run(ctx, "search_text", query="zzzzqq").startswith("No matches")


def test_the_jack_scenario_find_then_edit_that_row(ctx: Ctx, people: Path, asker: Asker):
    ctx.selected = str(people)
    out = run(ctx, "sheet_find", text="Jack", column="Name")
    assert "2 matching" in out and "row 2" in out and "row 4" in out
    # two rows in focus -> the model must say which one
    assert "pass row" in run(ctx, "sheet_set_cell", column="Age", value="98")
    # a narrower search leaves exactly one row in focus
    run(ctx, "sheet_find", text="Jack", column="Country")  # none
    out = run(ctx, "sheet_find", text="India")
    assert "1 matching" in out
    assert run(ctx, "sheet_set_cell", column="Age", value="98", expect="15").startswith("OK")
    assert values(people)[1][1] == 98
    assert "Age: 15  ->  98" in asker.asked[-1][1]


def test_sheet_set_cell_is_undoable(ctx: Ctx, people: Path):
    before = people.read_bytes()
    run(ctx, "sheet_find", text="Jill", path=str(people))
    assert run(ctx, "sheet_set_cell", column="Age", value="30").startswith("OK")
    assert people.read_bytes() != before
    ctx.journal.undo()
    assert people.read_bytes() == before


def test_sheet_set_cell_guards(ctx: Ctx, people: Path, root: Path, asker: Asker):
    p = str(people)
    assert "which file" in run(ctx, "sheet_info")
    assert "not a spreadsheet" in run(ctx, "sheet_info", path="notes.txt")
    assert "holds '15', not '99'" in run(ctx, "sheet_set_cell", path=p, row=2, column="Age", value="1", expect="99")
    assert "no column" in run(ctx, "sheet_set_cell", path=p, row=2, column="Salary", value="1")
    assert "does not exist" in run(ctx, "sheet_set_cell", path=p, row=99, column="Age", value="1")
    assert "no sheet called" in run(ctx, "sheet_set_cell", path=p, row=2, column="Age", value="1", sheet="Nope")
    assert "formula" in run(ctx, "sheet_set_cell", path=p, row=4, column="Score", value="1")
    asker.answer = False
    assert run(ctx, "sheet_set_cell", path=p, row=2, column="Age", value="1").startswith("DENIED")
    assert values(people)[1][1] == 15


def test_sheet_info_and_find_across_sheets(ctx: Ctx, people: Path):
    out = run(ctx, "sheet_info", path=str(people))
    assert "Name (A)" in out and "sheet 'Other'" in out
    out = run(ctx, "sheet_find", path=str(people), text="hat")
    assert "[Other] row 2" in out
    assert "No row contains" in run(ctx, "sheet_find", path=str(people), text="Zed", column="Name")
    assert "no column" in run(ctx, "sheet_find", path=str(people), text="x", column="Salary", sheet="People")


def test_replace_and_append_text_work_on_docx(ctx: Ctx, word: Path):
    ambiguous = run(ctx, "replace_text", path=str(word), old="1200", new="900")
    assert "appears 2 times" in ambiguous
    assert "not found" in run(ctx, "replace_text", path=str(word), old="nope", new="x")
    assert run(ctx, "replace_text", path=str(word), old="deposit is 1200", new="deposit is 900").startswith("OK")
    assert "deposit is 900 dollars" in Document(word).paragraphs[1].text
    assert run(ctx, "append_text", path=str(word), text="Added line").startswith("OK")
    assert Document(word).paragraphs[-1].text == "Added line"
    assert "cannot create a new .docx" in run(ctx, "append_text", path=str(word.parent / "new.docx"), text="x")
    ctx.journal.undo()
    ctx.journal.undo()
    assert Document(word).paragraphs[1].text == "The deposit is 1200 dollars & due Friday."


