# ------------------------------------------------------------------ pdf (read-only)

def make_pdf(path: Path, pages: list[str]) -> None:
    from reportlab.pdfgen import canvas
    c = canvas.Canvas(str(path))
    for text in pages:
        if text:
            c.drawString(72, 720, text)
        c.showPage()
    c.save()


def test_pdf_is_read_searched_and_found(ctx: Ctx, root: Path):
    pdf = root / "docs" / "contract.pdf"
    make_pdf(pdf, ["Tenant agrees to a deposit of 900 dollars", "Second page mentions parking"])
    text = readers.read_text(str(pdf))
    assert "[page 1]" in text and "deposit of 900" in text and "[page 2]" in text and "parking" in text
    ctx.index.sync()
    assert str(pdf) in run(ctx, "search_text", query="parking", kind="pdf")
    assert [f.path for f in finder.search(ctx, "parking", "pdf")[0]] == [str(pdf)]
    assert "deposit" in run(ctx, "read_file", path=str(pdf))


def test_pdf_cannot_be_edited_and_says_so(ctx: Ctx, root: Path):
    pdf = root / "c.pdf"
    make_pdf(pdf, ["hello"])
    before = pdf.read_bytes()
    for name, args in (("replace_text", {"old": "hello", "new": "bye"}), ("append_text", {"text": "x"}),
                       ("write_file", {"content": "x", "overwrite": True})):
        assert "not edit" in run_tool(ctx, name, {"path": "c.pdf", **args})
    assert pdf.read_bytes() == before


def test_pdf_without_text_or_without_pypdf_gives_clear_messages(root: Path, monkeypatch: pytest.MonkeyPatch):
    blank = root / "scan.pdf"
    make_pdf(blank, [""])
    with pytest.raises(readers.UnreadableError, match="no selectable text"):
        readers.read_text(str(blank))
    broken = root / "broken.pdf"
    broken.write_bytes(b"%PDF-1.4 garbage")
    with pytest.raises(readers.UnreadableError):
        readers.read_text(str(broken))
    import builtins
    real = builtins.__import__

    def no_pypdf(name: str, *a: Any, **k: Any) -> Any:
        if name == "pypdf":
            raise ImportError(name)
        return real(name, *a, **k)
    monkeypatch.setattr(builtins, "__import__", no_pypdf)
    with pytest.raises(readers.UnreadableError, match="pip install pypdf"):
        readers.read_text(str(blank))


# ------------------------------------------------------------------ unusual workbook shapes (hand-built XML)

MAIN = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"


def build_xlsx(path: Path, sheet_xml: str, *, shared: str = "", workbook_pr: str = "", calc: str = "",
               target: str = "worksheets/sheet1.xml", styles: bool = True) -> None:
    wb = (f'<workbook xmlns="{MAIN}" xmlns:r="{REL}">{workbook_pr}<sheets><sheet name="S" sheetId="1" r:id="rId1"/></sheets>{calc}</workbook>')
    rels = (f'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            f'<Relationship Id="rId1" Type="x" Target="{target}"/></Relationships>')
    st = (f'<styleSheet xmlns="{MAIN}"><numFmts count="1"><numFmt numFmtId="164" formatCode="[$-409]dd\\-mmm\\-yy"/></numFmts>'
          '<cellXfs count="3"><xf numFmtId="0"/><xf numFmtId="14"/><xf numFmtId="164"/></cellXfs></styleSheet>')
    with zipfile.ZipFile(path, "w") as z:
        z.writestr("xl/workbook.xml", wb)
        z.writestr("xl/_rels/workbook.xml.rels", rels)
        z.writestr(target.lstrip("/") if target.startswith("/") else "xl/" + target, sheet_xml)
        if styles:
            z.writestr("xl/styles.xml", st)
        if shared:
            z.writestr("xl/sharedStrings.xml", shared)


def test_loader_handles_every_cell_type(root: Path):
    p = root / "odd.xlsx"
    sheet = (f'<worksheet xmlns="{MAIN}"><sheetData>'
             '<row r="1" spans="1:6"><c r="A1" t="s"><v>0</v></c><c r="B1" t="s"><v>1</v></c><c r="C1" t="inlineStr"><is><t>Inline</t></is></c></row>'
             '<row r="2"><c r="A2" t="b"><v>1</v></c><c r="B2" t="e"><v>#DIV/0!</v></c><c r="C2" t="str"><v>formula text</v></c>'
             '<c r="D2" s="1"><v>45000</v></c><c r="E2" s="2"><v>45000.5</v></c><c r="F2"><v>0.1</v></c></row>'
             '<row r="3"/><row r="4"><c><v>7</v></c><c><v>8</v></c></row>'
             '</sheetData></worksheet>')
    shared = (f'<sst xmlns="{MAIN}"><si><t>Plain</t></si><si><r><t>Rich </t></r><r><t>text</t></r><rPh><t>ignored</t></rPh></si></sst>')
    build_xlsx(p, sheet, shared=shared)
    sh = sheets.load(str(p))[0]
    assert sh.get(1, 1) == "Plain" and sh.get(1, 2) == "Rich text" and sh.get(1, 3) == "Inline"
    assert sh.get(2, 1) == "TRUE" and sh.get(2, 2) == "#DIV/0!" and sh.get(2, 3) == "formula text"
    assert sh.get(2, 4) == "2023-03-15" and sh.get(2, 5) == "2023-03-15 12:00" and sh.get(2, 6) == "0.1"
    assert sh.get(4, 1) == "7" and sh.get(4, 2) == "8"           # cells without r= are numbered in order
    assert 3 not in sh.cells and {(2, 4), (2, 5)} <= sh.date_cells


def test_1904_dates_and_absolute_sheet_targets(root: Path):
    p = root / "mac.xlsx"
    sheet = f'<worksheet xmlns="{MAIN}"><sheetData><row r="1"><c r="A1" s="1"><v>0</v></c></row></sheetData></worksheet>'
    build_xlsx(p, sheet, workbook_pr='<workbookPr date1904="1"/>', target="/xl/worksheets/sheet9.xml")
    assert sheets.load(str(p))[0].get(1, 1) == "1904-01-01"


def test_missing_parts_are_clean_errors(root: Path):
    p = root / "x.xlsx"
    with zipfile.ZipFile(p, "w") as z:
        z.writestr("hello.txt", "hi")
    with pytest.raises(sheets.SheetError, match="no 'xl/workbook.xml'"):
        sheets.load(str(p))
    with pytest.raises(sheets.SheetError, match="only .xlsx"):
        sheets.load(str(root / "notes.txt"))


def test_patching_odd_layouts(root: Path):
    p = root / "odd.xlsx"
    sheet = (f'<worksheet xmlns="{MAIN}"><sheetData>'
             '<row r="1" spans="1:3"><c r="A1" t="inlineStr"><is><t>H</t></is></c><c r="C1"><v>3</v></c></row>'
             '<row r="2"/><row r="5"><c r="A5"><v>1</v></c></row></sheetData></worksheet>')
    build_xlsx(p, sheet)
    sh = sheets.load(str(p))[0]
    sheets.set_cell(str(p), sh, 1, 2, "mid")        # between two cells of a row that has spans
    sheets.set_cell(str(p), sh, 2, 1, "empty-row")  # self-closing row
    sheets.set_cell(str(p), sh, 3, 1, "new-row")    # a row between existing rows
    sheets.set_cell(str(p), sh, 9, 1, "last-row")   # after the last row
    got = sheets.load(str(p))[0]
    assert (got.get(1, 1), got.get(1, 2), got.get(1, 3)) == ("H", "mid", "3")
    assert got.get(2, 1) == "empty-row" and got.get(3, 1) == "new-row" and got.get(5, 1) == "1" and got.get(9, 1) == "last-row"
    assert got.rows == [1, 2, 3, 5, 9]
    with zipfile.ZipFile(p) as z:
        assert 'spans' not in z.read("xl/worksheets/sheet1.xml").decode().split("</row>")[0]


def test_patch_into_empty_sheetdata_and_bad_layouts(root: Path):
    p = root / "empty.xlsx"
    build_xlsx(p, f'<worksheet xmlns="{MAIN}"><sheetData/></worksheet>')
    sheets.set_cell(str(p), sheets.Sheet("S", part="xl/worksheets/sheet1.xml"), 1, 1, "first")
    assert sheets.load(str(p))[0].get(1, 1) == "first"
    with pytest.raises(sheets.SheetError, match="layout"):
        sheets._patch_sheet_xml("<worksheet/>", 1, 1, "x", False)


def test_text_cells_stay_text_and_numbers_stay_numbers(root: Path):
    p = root / "ids.xlsx"
    sheet = (f'<worksheet xmlns="{MAIN}"><sheetData><row r="1"><c r="A1" t="s"><v>0</v></c><c r="B1"><v>5</v></c></row>'
             '</sheetData></worksheet>')
    build_xlsx(p, sheet, shared=f'<sst xmlns="{MAIN}"><si><t>00123</t></si></sst>')
    sh = sheets.load(str(p))[0]
    sheets.set_cell(str(p), sh, 1, 1, "90210")      # was text: must not turn into a number
    sheets.set_cell(str(p), sh, 1, 2, "6")          # was a number: stays a number
    with zipfile.ZipFile(p) as z:
        xml = z.read("xl/worksheets/sheet1.xml").decode()
    assert 't="inlineStr"' in xml and "<v>6</v>" in xml and "<v>90210</v>" not in xml
    assert sheets.load(str(p))[0].get(1, 1) == "90210"


def test_numeric_looking_values(root: Path):
    for v, numeric in (("98", True), ("-1.5", True), ("1e3", True), ("007", False), ("1234567890123456", False), ("12abc", False),
                       ("0.5", True), ("0", True)):
        assert sheets._looks_numeric(v) is numeric, v


def test_bad_dates_and_forced_recalc_variants():
    assert "<v>45000</v>" in sheets._cell_xml("A1", "1", "2023-03-15", True)
    with pytest.raises(sheets.SheetError, match="valid date"):
        sheets._cell_xml("A1", "1", "2023-02-31", True)
    assert "inlineStr" in sheets._cell_xml("A1", "1", "tomorrow", True)       # not an ISO date -> kept as text
    assert sheets._cell_xml("A1", "", "", False) == '<c r="A1"/>'
    wb = '<workbook><sheets/><calcPr calcId="1"/></workbook>'
    assert 'fullCalcOnLoad="1"' in sheets._force_recalc(wb) and sheets._force_recalc(sheets._force_recalc(wb)).count("fullCalcOnLoad") == 1
    assert '<calcPr fullCalcOnLoad="1"/></workbook>' in sheets._force_recalc("<workbook><sheets/></workbook>")
    assert sheets._force_recalc("<x/>") == "<x/>"


def test_csv_edge_cases(root: Path):
    p = root / "e.csv"
    p.write_text("a,b\n1,2", encoding="utf-8")                       # no trailing newline
    sheets.set_cell(str(p), sheets.load(str(p))[0], 2, 2, "9")
    assert p.read_text() == "a,b\n1,9"
    sheets.set_cell(str(p), sheets.load(str(p))[0], 4, 3, "far")      # beyond the end pads rows and columns
    assert p.read_text() == "a,b\n1,9\n\n,,far"
    p.write_bytes(b"\xff\xfe\x00bad")
    with pytest.raises(sheets.SheetError, match="UTF-8"):
        sheets.load(str(p))
    (root / "empty.csv").write_text("")
    assert sheets.load_csv(str(root / "empty.csv"))[0].cells == {}
    assert sheets.col_letters(27) == "AA" and sheets.col_index("AA") == 27
    with pytest.raises(sheets.SheetError, match="unsupported cell"):
        sheets._ref("$A$1")


def test_kind_is_understood_the_way_small_models_write_it(ctx: Ctx, people: Path):
    for raw, want in (("Excel files", "excel"), (".xlsx", "excel"), ("spreadsheets", "excel"), ("PDF", "pdf"), ("Word document", "word"),
                      ("", ""), ("all", "")):
        assert finder.normalize_kind(raw) == want, raw
    assert finder.normalize_kind("banana") is None
    for raw in ("Excel files", "xlsx", "spreadsheet"):
        assert str(people) in run(ctx, "search_text", query="Country", kind=raw)
    assert "kind must be" in run(ctx, "search_text", query="x", kind="banana")
    assert finder.normalize_kind("photos") == "image" and finder.normalize_kind("Music") == "audio"


# ------------------------------------------------------------------ listing by kind, nested trusted folders

@pytest.fixture
def nested(root: Path, hh: Path, asker: Asker):
    """The user's real setup: a folder AND a folder inside it are both trusted."""
    from hearth.access import Access
    from hearth.index import Index
    from hearth.journal import Journal
    inner = root / "docs"
    box = Access([inner, root], protected=[hh])
    return Ctx(box, Index(hh / "index.db", box), Journal(hh), asker, choose=asker.pick)


def test_kind_only_lists_every_file_of_that_kind(nested: Ctx, root: Path, people: Path):
    other = root / "docs" / "inventory.xlsx"
    other.write_bytes(people.read_bytes())
    (root / "~$people.xlsx").write_bytes(b"lock")
    out = run(nested, "find_files", kind="excel")                          # no name at all
    assert out.count(".xlsx  (") == 2 and str(people) in out and str(other) in out and "~$" not in out
    assert out.startswith("2 match(es)")                                   # nested trusted folders are not listed twice
    assert set(nested.found) == {str(other), str(people)}


def test_find_files_with_folder_and_empty_results(nested: Ctx, root: Path, people: Path):
    assert run(nested, "find_files", kind="Excel files", folder=str(root / "docs")).startswith("No matching files under")
    assert str(people) in run(nested, "find_files", kind="excel", folder=str(root))
    assert "No matching" in run(nested, "find_files", kind="word")
    assert "give a name pattern" in run(nested, "find_files")
    assert "give a name pattern" in run(nested, "find_files", pattern="  ")
    assert "kind must be" in run(nested, "find_files", kind="banana")


def test_search_with_a_query_can_be_limited_to_a_folder(nested: Ctx, root: Path, people: Path):
    nested.index.sync()
    assert str(people) in run(nested, "search_text", query="Country", kind="excel")
    assert "No matches" in run(nested, "search_text", query="Country", kind="excel", folder=str(root / "docs"))


def test_nested_trusted_folders_list_as_one(nested: Ctx, root: Path):
    out = run(nested, "list_folder")                                       # two roots, one inside the other -> one folder
    assert "notes.txt" in out and "Places on this computer" not in out
    assert out.count("lease.md") == 0 and "docs/" in out
